WITH filtered AS (SELECT *, LENGTH(page) AS page_length FROM web_events WHERE page IS NOT NULL), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_id, SIZE(COLLECT_SET(page)) AS num_pages, SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) AS page_view_duration_sec, COUNT_IF(event_type = 'add_to_cart') AS add_to_cart_events, COUNT(*) AS num_rows, APPROX_PERCENTILE(is_new_burst, 0.9) AS is_new_burst_p90, MAX(event_time) AS last_event_time FROM sessionized GROUP BY session_id HAVING SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) > 0;
